import React, { useState } from 'react';

// FilePreview: shows image/video preview and simple editing controls
// Props: file (dataURL), type ('image'|'video'), index, onRemove(index), onUpdate(index, newDataURL)

function applyFilterToDataURL(dataUrl, filter) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      // apply CSS filter via ctx.filter
      ctx.filter = filter || 'none';
      ctx.drawImage(img, 0, 0);
      resolve(canvas.toDataURL('image/jpeg', 0.92));
    };
    img.src = dataUrl;
  });
}

function cropCenterSquare(dataUrl) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      const size = Math.min(img.width, img.height);
      const sx = (img.width - size) / 2;
      const sy = (img.height - size) / 2;
      const canvas = document.createElement('canvas');
      canvas.width = size; canvas.height = size;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, sx, sy, size, size, 0, 0, size, size);
      resolve(canvas.toDataURL('image/jpeg', 0.92));
    };
    img.src = dataUrl;
  });
}

export default function FilePreview({ file, type, index, onRemove, onUpdate }) {
  const [filter, setFilter] = useState('none');
  const [loading, setLoading] = useState(false);

  const filters = [
    { key: 'none', label: '원본', css: 'none' },
    { key: 'sepia', label: '세피아', css: 'sepia(0.45)' },
    { key: 'bw', label: '흑백', css: 'grayscale(1)' },
    { key: 'bright', label: '밝게', css: 'brightness(1.15)' },
    { key: 'contrast', label: '선명', css: 'contrast(1.12) saturate(1.05)' },
  ];

  const handleApplyFilter = async (f) => {
    if (type !== 'image') return;
    setLoading(true);
    try {
      const newData = await applyFilterToDataURL(file, f.css);
      setFilter(f.key);
      onUpdate(index, newData);
    } catch (e) {
      console.error(e);
    } finally { setLoading(false); }
  };

  const handleCrop = async () => {
    if (type !== 'image') return;
    setLoading(true);
    try {
      const newData = await cropCenterSquare(file);
      onUpdate(index, newData);
    } catch (e) {
      console.error(e);
    } finally { setLoading(false); }
  };

  return (
    <div style={{ position: 'relative', border: '1px solid #eee', borderRadius: 8, overflow: 'hidden', background: '#fff' }}>
      <div style={{ width: '100%', height: 180, display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#fafafa' }}>
        {type === 'video' ? (
          <video src={file} controls style={{ maxWidth: '100%', maxHeight: '100%' }} />
        ) : (
          <img src={file} alt={`preview-${index}`} style={{ maxWidth: '100%', maxHeight: '100%', display: 'block' }} />
        )}
      </div>

      <div style={{ padding: 8, display: 'flex', gap: 8, alignItems: 'center', justifyContent: 'space-between' }}>
        <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
          <button type="button" onClick={() => onRemove(index)} style={{ border: 'none', background: '#ff6b6b', color: '#fff', padding: '6px 8px', borderRadius: 6, cursor: 'pointer' }}>삭제</button>
          {type === 'image' && (
            <>
              <button type="button" onClick={handleCrop} style={{ border: '1px solid #ddd', background: '#fff', padding: '6px 8px', borderRadius: 6, cursor: 'pointer' }}>{loading ? '처리중...' : '정사각 자르기'}</button>
              <select value={filter} onChange={(e) => { const f = filters.find(x => x.key === e.target.value); handleApplyFilter(f); }} style={{ padding: '6px', borderRadius: 6 }}>
                {filters.map(f => <option key={f.key} value={f.key}>{f.label}</option>)}
              </select>
            </>
          )}
        </div>
        <div style={{ fontSize: 12, color: '#777' }}>{type === 'video' ? '동영상' : '이미지'}</div>
      </div>
    </div>
  );
}
